export const getGetDatasetRecordsUrl = (id: string,
    params?: GetDatasetRecordsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/datasets/${id}/records?${stringifiedParams}` : `/api/datasets/${id}/records`
}

